FUNCTION_BLOCK FB_S05
VAR_INPUT
    FlowPulse : BOOL;
    ShiftReset : BOOL;
    CycleTime : TIME;
END_VAR
VAR_OUTPUT
    TotalVolume : LREAL;
    ShiftVolume : LREAL;
    PulseCount : UDINT;
    OverflowFlag : BOOL;
    Status : WORD;
END_VAR
VAR
    FlowPulseLast : BOOL := FALSE;
    ShiftResetLast : BOOL := FALSE;
    FirstScan : BOOL := TRUE;

    ScanCounter : UDINT := 0;
    LastPulseScan : UDINT := 0;
    PulseEdge : BOOL;
    ResetEdge : BOOL;
    PulseTooFastThisScan : BOOL;

    MAX_VOLUME : LREAL := 1000000.0;
    PULSE_VOLUME : LREAL := 0.5;
END_VAR
(*
    需求冲突/未决项报告：
    1) K4 要求检测同一扫描周期内两次以上 FlowPulse 上升沿，但接口仅有扫描级 BOOL 输入，
       无法观测 20 ms 扫描内部发生的多次脉冲。本实现不新增硬件锁存接口，仅在采样到
       相邻扫描上升沿间隔 <= 1 个扫描周期时保守置 Status = 16#8501，并且每扫描最多计 1 个脉冲。
    2) K1 要求每个上升沿 TotalVolume 与 ShiftVolume 都加 0.5 L；K3/C1 要求 TotalVolume
       达到 1000000.0 后不再增长；C6 要求 ShiftVolume <= TotalVolume。本实现优先保持
       TotalVolume 上限和 C6：溢出后 TotalVolume 冻结，ShiftVolume 仅在不超过 TotalVolume
       时继续增加，PulseCount 仍继续累计采样到的上升沿。该行为与 K1 在溢出后的字面要求存在冲突。
*)
IF FirstScan THEN
    TotalVolume := 0.0;
    ShiftVolume := 0.0;
    PulseCount := 0;
    OverflowFlag := FALSE;
    Status := 16#0000;

    FlowPulseLast := FlowPulse;
    ShiftResetLast := ShiftReset;

    ScanCounter := 0;
    LastPulseScan := 0;
    PulseTooFastThisScan := FALSE;

    FirstScan := FALSE;
ELSE
    ScanCounter := ScanCounter + 1;
    PulseTooFastThisScan := FALSE;

    PulseEdge := FlowPulse AND NOT FlowPulseLast;
    ResetEdge := ShiftReset AND NOT ShiftResetLast;

    FlowPulseLast := FlowPulse;
    ShiftResetLast := ShiftReset;

    IF PulseEdge THEN
        (* 扫描级过快保守判断：相邻扫描均检测到上升沿时报告 16#8501。 *)
        IF (CycleTime > T#0ms) AND (LastPulseScan > 0) AND ((ScanCounter - LastPulseScan) <= 1) THEN
            PulseTooFastThisScan := TRUE;
        END_IF;
        LastPulseScan := ScanCounter;

        (* 总量累加：达到 1000000.0 后冻结，不再增长。 *)
        IF NOT OverflowFlag THEN
            IF TotalVolume + PULSE_VOLUME <= MAX_VOLUME THEN
                TotalVolume := TotalVolume + PULSE_VOLUME;
            ELSE
                TotalVolume := MAX_VOLUME;
            END_IF;

            IF TotalVolume >= MAX_VOLUME THEN
                OverflowFlag := TRUE;
            END_IF;
        END_IF;

        (* 当班脉冲数按采样到的上升沿累计。 *)
        PulseCount := PulseCount + 1;

        (* 当班流量增加，但受 C6: ShiftVolume <= TotalVolume 限制。 *)
        IF ShiftVolume + PULSE_VOLUME <= TotalVolume THEN
            ShiftVolume := ShiftVolume + PULSE_VOLUME;
        ELSE
            ShiftVolume := TotalVolume;
        END_IF;
    END_IF;

    (* ShiftReset 上升沿清清当班量；TotalVolume 与 OverflowFlag 不受影响。 *)
    IF ResetEdge THEN
        ShiftVolume := 0.0;
        PulseCount := 0;
    END_IF;

    (* Status 优先级：本扫描脉冲过快 > 总量溢出 > 正常。 *)
    IF PulseTooFastThisScan THEN
        Status := 16#8501;
    ELSIF OverflowFlag OR (TotalVolume >= MAX_VOLUME) THEN
        Status := 16#8502;
    ELSE
        Status := 16#0000;
    END_IF;
END_IF;
END_FUNCTION_BLOCK
